// Canonical SLA tier table — the single source of truth for the public
// `/sla` page (`client/src/pages/sla.tsx`), the in-app SLA enforcement
// (`server/support/slaPolicy.ts`), and the human-readable contractual
// reference (`docs/sla.md`, regenerated by `scripts/generate-sla-doc.ts`
// and verified by `scripts/check-sla-doc.mjs`).
//
// IMPORTANT: this module is the ONLY place SLA targets may be edited. Any
// change MUST be followed by `npx tsx scripts/generate-sla-doc.ts` so
// `docs/sla.md` is rewritten; CI fails the build if the markdown table
// drifts from this file.
//
// The module is framework-free on purpose so both the React client and
// the Express server can import it directly.

export type SupportTier = "starter" | "pro" | "enterprise";
export type SupportPriority = "low" | "normal" | "high" | "urgent";
export type SlaClock = "wall" | "business";

export interface SlaTarget {
  /** Numeric amount in `unit`. */
  amount: number;
  unit: "minutes" | "hours";
  /**
   * "wall"     → straight wall-clock minutes from creation (24×7).
   * "business" → business-hours math (Mon–Fri 09:00–18:00 UTC, skipping
   *               US federal holidays). Per-tenant TZ is a roadmap item.
   */
  clock: SlaClock;
}

export interface SlaPolicy {
  /** Monthly uptime target, in percent (e.g. 99.9). */
  uptimeTargetPct: number;
  /** Display labels for the supported channels, in order. */
  channels: readonly string[];
  /** Status-page incident update cadence, human-readable. */
  statusUpdateCadence: string;
  /** First-response targets, keyed by priority. */
  firstResponse: Readonly<Record<SupportPriority, SlaTarget>>;
  /** Resolution targets, keyed by priority. */
  resolution: Readonly<Record<SupportPriority, SlaTarget>>;
}

const BH = (amount: number, unit: "minutes" | "hours" = "minutes"): SlaTarget => ({
  amount,
  unit,
  clock: "business",
});
const WALL = (amount: number, unit: "minutes" | "hours"): SlaTarget => ({
  amount,
  unit,
  clock: "wall",
});

export const SLA_TIERS: Readonly<Record<SupportTier, SlaPolicy>> = {
  starter: {
    uptimeTargetPct: 99.5,
    channels: ["In-app", "email"],
    statusUpdateCadence: "Best effort",
    firstResponse: {
      urgent: BH(8 * 60),    // 1 business day
      high: BH(8 * 60),      // 1 business day
      normal: BH(16 * 60),   // 2 business days
      low: BH(24 * 60),      // 3 business days
    },
    resolution: {
      urgent: BH(40, "hours"),  // 5 business days
      high: BH(64, "hours"),    // 8 business days
      normal: BH(96, "hours"),  // 12 business days
      low: BH(120, "hours"),    // 15 business days
    },
  },
  pro: {
    uptimeTargetPct: 99.9,
    channels: ["In-app", "email", "Slack"],
    statusUpdateCadence: "≤ 60 min cadence",
    firstResponse: {
      urgent: BH(4 * 60),    // 4 business hours
      high: BH(4 * 60),      // 4 business hours
      normal: BH(8 * 60),    // 1 business day
      low: BH(16 * 60),      // 2 business days
    },
    resolution: {
      urgent: WALL(48, "hours"),  // 2 calendar days
      high: WALL(72, "hours"),
      normal: WALL(96, "hours"),
      low: WALL(120, "hours"),
    },
  },
  enterprise: {
    uptimeTargetPct: 99.95,
    channels: ["In-app", "email", "Slack", "CSM"],
    statusUpdateCadence: "≤ 30 min cadence",
    firstResponse: {
      urgent: WALL(30, "minutes"), // 30 minutes, 24×7
      high: BH(60),                // 1 business hour
      normal: BH(4 * 60),          // 4 business hours
      low: BH(8 * 60),             // 1 business day
    },
    resolution: {
      urgent: WALL(8, "hours"),
      high: WALL(16, "hours"),
      normal: WALL(24, "hours"),
      low: WALL(48, "hours"),
    },
  },
};

export const SUPPORT_TIERS: readonly SupportTier[] = ["starter", "pro", "enterprise"] as const;
export const SUPPORT_PRIORITIES: readonly SupportPriority[] = ["low", "normal", "high", "urgent"] as const;

export const SUPPORT_TIER_LABELS: Readonly<Record<SupportTier, string>> = {
  starter: "Starter",
  pro: "Pro",
  enterprise: "Enterprise",
};
